for p in b.get('projects',[]):
    name=p['path'].split('/')[-1]
    for fw in p.get('frameworks',[]):
        for pkg in fw.get('topLevelPackages',[]):
            print(f'  {name}: {pkg[\"id\"]} {pkg[\"resolvedVersion\"]}')
print()
print('=== AFTER CPM ===')
